package com.zerotrust.internalresource.entity;
import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="device_resources") public class DeviceResourceEntity{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false,updatable=false)private String resourceId;@Column(nullable=false)private String deviceName;@Column(nullable=false)private String ipAddress;@Column(nullable=false)private String deviceType;@Column(nullable=false)private String location;@Column(nullable=false)private String department;@Column(nullable=false)private String securityLevel;@Column(nullable=false)private String status;private Instant lastHeartbeat;@Column(nullable=false)private Instant createdAt;@Column(nullable=false)private Instant updatedAt;public DeviceResourceEntity(){}public Long getId(){return id;}public String getResourceId(){return resourceId;}public void setResourceId(String v){resourceId=v;}public String getDeviceName(){return deviceName;}public void setDeviceName(String v){deviceName=v;}public String getIpAddress(){return ipAddress;}public void setIpAddress(String v){ipAddress=v;}public String getDeviceType(){return deviceType;}public void setDeviceType(String v){deviceType=v;}public String getLocation(){return location;}public void setLocation(String v){location=v;}public String getDepartment(){return department;}public void setDepartment(String v){department=v;}public String getSecurityLevel(){return securityLevel;}public void setSecurityLevel(String v){securityLevel=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public Instant getLastHeartbeat(){return lastHeartbeat;}public void setLastHeartbeat(Instant v){lastHeartbeat=v;}public Instant getCreatedAt(){return createdAt;}public void setCreatedAt(Instant v){createdAt=v;}public Instant getUpdatedAt(){return updatedAt;}public void setUpdatedAt(Instant v){updatedAt=v;}}
